arguments.new_string:
threshold = flood_stages[site_code]

values = ts.get('values', [])[0].get('value', [])
flood_count = 0
max_val_debug = -9999.0

for val_obj in values:
    val = val_obj.get('value')
    # USGS uses -999999 for no data
    if val and float(val) != -999999:
        try:
            f_val = float(val)
            if f_val > max_val_debug:
                max_val_debug = f_val

            if f_val > threshold:
                flood_count += 1
        except ValueError:
            pass

# Debug print
print(f"Debug: Station {site_code} Max Stage: {max_val_debug} Flood Stage: {threshold}")

if flood_count > 0:
    results[site_code] = flood_count
